/* eslint-env jest */
'use strict';

const os = require('os');
const _ = require('lodash');

const yandexLogger = require('../../src');

describe('YandexLogger. Middleware. Secure Field', () => {
    let logger;
    let stream;
    let jestFakeTimers;
    let baseRecord;

    beforeEach(() => {
        stream = { write: jest.fn() };

        baseRecord = {
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
        };

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен обфусцировать переданные поля', () => {
        logger = getLogger({
            fields: [
                'data.a',
                'data.b.c',
                'data.obj',
                'data.empty',
                'data.number',
                'foo',
            ],
        });

        let data = {
            a: 'value-123',
            b: {
                c: 'd',
            },
            obj: {},
            empty: '',
            number: 123,
            bypass: 'value',
        };
        let dataClone = _.cloneDeep(data);

        logger.info({ data, foo: 'bar' }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            data: {
                a: 'valuXXXXX',
                b: {
                    c: 'X',
                },
                obj: {},
                empty: '',
                number: 123,
                bypass: 'value',
            },
            foo: 'bXX',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);

        expect(data).toStrictEqual(dataClone, 'Оригинальный объект не должен мутировать');
    });

    it('должен использовать функцию обфускации из конфига', () => {
        logger = getLogger({
            fields: ['data.foo'],
            secureValue(value) {
                return `${value}-secured!`;
            },
        });

        let data = {
            foo: 'value',
        };
        let dataClone = _.cloneDeep(data);

        logger.info({ data }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            data: {
                foo: 'value-secured!',
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);

        expect(data).toStrictEqual(dataClone, 'Оригинальный объект не должен мутировать');
    });

    it('не должен копировать объекты, если значение не изменилось', () => {
        logger = getLogger({
            fields: [
                'data.foo',
            ],
        });

        let data = {
            foo: '',
        };
        let dataClone = _.cloneDeep(data);

        logger.info({ data }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            data: {
                foo: '',
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);

        expect(stream.write.mock.calls[0][0].data).toBe(data);
        expect(data).toStrictEqual(dataClone, 'Оригинальный объект не должен мутировать');
    });

    it('должен работать без конфига', () => {
        logger = getLogger();

        logger.info({ foo: 'bar' }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            foo: 'bar',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    function getLogger(config) {
        return yandexLogger({
            streams: [
                { stream },
            ],
            middleware: [
                require('../../middleware/secure-field')(config),
            ],
        });
    }
});
